102|cbor_item_t* cbor_new_definite_array(size_t size) {
103|  cbor_item_t* item = _cbor_malloc(sizeof(cbor_item_t));
104|  _CBOR_NOTNULL(item);
105|
106|  // malloc(0) may legitimately return NULL, so do not allocate (or check) for
107|  // an empty array. The data pointer is never dereferenced while size == 0.
108|  cbor_item_t** data = NULL;
