137|    cbor_item_t* array_item = cbor_new_definite_array(1);
138|    assert(cbor_array_push(array_item, cbor_move(cbor_build_uint8(42))));
139|    cbor_item_t* first_array_element = cbor_array_get(array_item, 0);
